      "path": "src/app/(crm)/clientes/page.tsx",
      "content": "import type { Metadata } from "next";
import Link from "next/link";
import { connection } from "next/server";
import { Suspense } from "react";
import { ButtonLink } from "@/components/button";
import { Loading, PageHeader } from "@/components/page-header";
import { EmptyRow, Table, Td, Th, Tr } from "@/components/table";
import { listClients } from "./queries";

export const metadata: Metadata = { title: "Clientes · crm-demo" };

interface Props {
  searchParams: Promise<{ q?: string; query?: string }>;
}

export default function ClientsPage({ searchParams }: Props) {
  return (
    <>
      <PageHeader
        title="Clientes"
        actions={
          <ButtonLink href="/clientes/nuevo" data-testid="new-client-button">
            Nuevo cliente
          </ButtonLink>
        }
      />
      <Suspense fallback={<Loading />}>
        <ClientSearchAndTable searchParams={searchParams} />
      </Suspense>
    </>
  );
}

async function ClientSearchAndTable({ searchParams }: Props) {
  await connection();
  const resolvedParams = await searchParams;
  const query = resolvedParams.q ?? resolvedParams.query ?? "";
  const clients = await listClients(query);

  return (
    <div className="space-y-4">
      <form method="get" className="flex max-w-sm items-center gap-2">
        <input
          type="search"
          name="q"
          defaultValue={query}
          placeholder="Buscar cliente por nombre o email..."
          data-testid="client-search-input"
          className="block w-full rounded-md border border-slate-300 bg-white px-3 py-2 text-sm shadow-xs focus:border-blue-600 focus:outline-none focus:ring-1 focus:ring-blue-600"
        />
      </form>

      <Table data-testid="clients-table">
        <thead>
          <tr>
            <Th>Nombre</Th>
            <Th className="hidden sm:table-cell">Empresa</Th>
            <Th className="hidden md:table-cell">Email</Th>
            <Th className="hidden md:table-cell">Teléfono</Th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {clients.length === 0 && (
            <EmptyRow colSpan={4}>Todavía no hay clientes.</EmptyRow>
          )}
          {clients.map((client) => (
            <Tr key={client.id} data-testid="client-row" data-id={client.id}>
              <Td>
                <Link
                  href={`/clientes/${client.id}`}
                  className="font-medium text-blue-700 hover:underline"
                >
                  {client.name}
                </Link>
                <div className="text-xs text-slate-500 sm:hidden">
                  {client.company ?? client.email}
                </div>
              </Td>
              <Td className="hidden sm:table-cell">{client.company ?? "—"}</Td>
              <Td className="hidden md:table-cell">{client.email}</Td>
              <Td className="hidden whitespace-nowrap md:table-cell">
                {client.phone ?? "—"}
              </Td>
            </Tr>
          ))}
        </tbody>
      </Table>
    </div>
  );
}
